fn walk_to_workspace() -> PathBuf {
    let mut dir = if let Ok(m) = std::env::var("CARGO_MANIFEST_DIR") {
        PathBuf::from(m)
    } else {
        std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
    };
    let mut i = 0usize;
    while i < 12 {
        let env = dir.join("AEP-Components/envelope/crate/src/lib.rs");
        if env.is_file() {
            return dir;
        }
        match dir.parent() {
            Some(parent) => dir = parent.to_path_buf(),
            None => break,
        }
        i = i.saturating_add(1);
    }
    PathBuf::from(".")
}

fn read_src(path: &PathBuf, label: &str) -> Result<String, String> {
    if path.is_file() == false {
        return Err(format!("missing {label} source"));
    }
    match fs::read_to_string(path) {
        Ok(v) => {
            if v.is_empty() {
                Err(format!("empty {label} source"))
            } else {
                Ok(v)
            }
        }
        Err(e) => Err(e.to_string()),
    }
}

pub fn run_gate() -> Result<i32, String> {
    let root = walk_to_workspace();
    let envelope = root.join("AEP-Components/envelope/crate/src/lib.rs");
    let seq = root.join("AEP-Components/envelope/crate/src/seq_walls.rs");
    let dynaep = root.join("AEP-Components/dynAEP/crate/src/lib.rs");
    let temporal = root.join("AEP-Components/admit-temporal-bounds/crate/src/compile.rs");
    let live = root.join("AEP-Components/live-entry/crate/src/lib.rs");
    let env_src = read_src(&envelope, "envelope")?;
    let seq_src = read_src(&seq, "seq_walls")?;
    let dyn_src = read_src(&dynaep, "dynaep")?;
    let tmp_src = read_src(&temporal, "compile_temporal")?;
    let live_src = read_src(&live, "live-entry")?;
    let proofs = [
        scan_wall_scene_missing(&env_src)?,
        scan_wall_time_missing(&env_src)?,
        scan_wall_channel_missing(&env_src)?,
        scan_wall_causal_missing(&seq_src)?,
        scan_dynaep_wall_time_missing(&dyn_src)?,
        scan_temporal_unbound(&tmp_src)?,
        admit_unbound_fields()?,
        scan_env034_stays(&live_src)?,
        scan_env042_stays(&env_src)?,
    ];
    let bound = bind_dest_dock_from_opened_frame("", "inference_engine");
    if bound.as_str() != "inference_engine" {
        return Err(String::from("dest_dock did not bind from opened frame docking port"));
    }
    for proof in proofs {
        let mut line = String::from("aep-unbound-field-close ok proof=");
        line.push_str(&proof);
        line.push('\n');
        let _ = std::io::stdout().write_all(line.as_bytes());
    }
    Ok(0)
}

