#[cfg(test)]
mod tests {
    use super::*;

    fn must(cond: bool) {
        if cond == false {
            std::process::abort();
        }
    }

    #[test]
    fn ticket_id() {
        must(TICKET == "AEP28-ENV-066");
        must(PARENT_TICKET_ENV034 == "AEP28-ENV-034");
        must(PARENT_TICKET_ENV042 == "AEP28-ENV-042");
    }

    #[test]
    fn wall_scene_open_on_missing_fails() {
        let bad = "fn wall_scene(action: &EnvelopeAction, snap: &Snapshot) -> WallVerdict { if action.scene_id.is_empty() { return wall(\"scene.membership\", \"scene\", true, \"no scene bound\"); } wall(\"scene.membership\", \"scene\", true, \"scene proven\") }";
        match scan_wall_scene_missing(bad) {
            Err(e) => must(e.contains("still opens scene.membership")),
            Ok(_) => std::process::abort(),
        }
    }

    #[test]
    fn wall_scene_close_on_missing_passes() {
        let good = "fn wall_scene(action: &EnvelopeAction, snap: &Snapshot) -> WallVerdict { if action.scene_id.is_empty() { return wall(\"scene.membership\", \"scene\", false, \"no scene bound\"); } if snap.proven_scene_ids.is_empty() { return wall(\"scene.membership\", \"scene\", false, \"empty proven scene set closes membership\"); } wall(\"scene.membership\", \"scene\", true, \"scene proven\") }";
        match scan_wall_scene_missing(good) {
            Ok(v) => must(v.contains("ok wall_scene closes on unbound scene")),
            Err(_) => std::process::abort(),
        }
    }

    #[test]
    fn dest_dock_binds_from_port() {
        must(bind_dest_dock_from_opened_frame("", "inference_engine") == "inference_engine");
        must(bind_dest_dock_from_opened_frame("dock-b", "inference_engine") == "dock-b");
    }

    #[test]
    fn admit_unbound_fields_runtime_closes() {
        match admit_unbound_fields() {
            Ok(v) => must(v.contains("ok missing scene")),
            Err(_) => std::process::abort(),
        }
    }

    #[test]
    fn hvvc_scan_process() {
        let mut st = scan_wall_scene_missing::ScanWallSceneMissing::new();
        st.src = String::from("fn wall_scene() { if action.scene_id.is_empty() { return wall(\"scene.membership\", \"scene\", true, \"no scene bound\"); } }");
        must(st.process().is_ok());
        must(st.scan.contains("still opens"));
    }
}
